b('b-formation','A1','raft.stepLeader, appendEntry, maybeCommit; ProgressTracker and quorum','Leader term and active simple/joint voter configuration','Proposal admission, durable MsgAppResp, or configuration replacement that calls maybeCommit',['s-proposal-read-admission','s-ack-commit','s-reset-authority','s-tracker','s-majority','s-joint','s-log-commit','s-config-commit'],implementation_guards=['Drop proposals from a removed leader or during transfer; configuration proposal checks use pendingConfIndex and joint status unless explicitly disabled.','MsgAppResp requires tracked sender; Step rejects old-term responses. maybeCommit requires an advancing index with current-term entry and active voting quorums.'],writes=['Assign proposal indexes and current term; append to unstable log; update sender Match and flow control; advance committed index.'],external_effects=['Broadcast append messages after commit advancement.'],important_branches=['Append-reply advancement calls releasePendingReadIndexMessages; switchToConfig advancement does not call that function.','Rejected append replies adjust probe position using index/term hints; duplicate nonadvancing replies need not retry commit.'],async_boundaries=['Self append support is a msgsAfterAppend response, consumed after persistence completion.'],produces_fact_ids=['f-commit'],cross_activity_effects={'A2':'Quorum support and current-term entries constrain decisions made by the active leader.','A5':'Committed indexes delimit application delivery.'})
b('b-authority','A2','raft.Step, hup, campaign, stepCandidate, reset, tickHeartbeat','Per-node term, role, vote, leader, voter configuration','Timer or Campaign/TimeoutNow; vote replies; higher-term messages; quorum loss',['s-election-entry','s-candidate-follower','s-term-dispatch','s-leadership','s-reset-authority','s-tally','s-joint','s-log-commit','s-restore','s-transfer','s-raw-interface','s-node-loop'],implementation_guards=['promotable requires local nonlearner progress and no pending snapshot; hup refuses unapplied committed configuration entries.','Vote requires acceptable prior vote/leader state and up-to-date candidate log; election result counts current voters in both joint halves.','Pre-votes do not increment local term; granted pre-vote responses may carry a future term. Lease check rejects nontransfer votes while the current leader is recent.'],writes=['A real campaign increments Term and votes for self; self vote is durability-delayed. Won quorum becomes leader and appends an empty entry.','reset discards vote tally, remote progress and readOnly quorum contexts, clears transfer and pendingConfIndex; log and committed prefix survive.'],important_branches=['Candidate steps down on same-term leader append/heartbeat/snapshot. Higher-term non-pre-vote traffic generally makes follower.','Old append-storage replies cannot stabilize entries, but their committed snapshot completion remains usable.','pendingReadIndexMessages is not cleared by reset; it is distinct from readOnly.'],consumes_fact_ids=['f-applied'],cross_activity_effects={'A1':'Resets prevent old match/vote support from being counted in a new leadership context; log freshness constrains future leaders.','A4':'Campaign admission scans only the suffix after raftLog.applied, so correctness depends on what that cursor acknowledges.'},unknowns=['Does permitted early Node.Advance allow the election configuration scan to omit configuration work still awaiting ApplyConfChange?'])
b('b-membership','A4','raft.applyConfChange/switchToConfig and confchange.Changer','Applied configuration; incoming/outgoing voters and staged learners','Caller applies a committed configuration entry or initialization/snapshot restores ConfState',['s-conf-change','s-conf-progress','s-conf-restore','s-restore','s-config-commit','s-proposal-read-admission','s-applied-auto','s-node-completion-contract','s-config-options'],legal_preconditions=['Apply committed changes in application order; disabled proposal validation requires caller serialization/verification.'],writes=['Simple changes affect at most one voter; joint changes retain outgoing voters, and leave-joint promotes staged learners and removes obsolete progress.','switchToConfig replaces the tracker and local learner status.'],important_branches=['Removed/demoted leader steps down only if configured, then returns; removed leader cannot admit proposals.','Retained leader recalculates commit with new quorum or probes peers, and aborts transfer if target is no longer a voter.','appliedTo may propose automatic leave-joint; this requires AutoLeave and leader role and sufficient applied progress.'],cross_activity_effects={'A1':'Reinterprets existing Match support against changed voting quorums.','A2':'Controls election eligibility and voting quorums; configuration application and applied cursor acknowledgement are separate calls.'})
b('b-recovery','A3','raft replication handlers, maybeSendAppend, maybeSendSnapshot and restore','Follower log matching and snapshot recovery','Incoming append/heartbeat/snapshot; leader retry from rejection, heartbeat or transport report',['s-replication-send','s-append-receive','s-log-append','s-restore','s-transfer','s-read-acks'],implementation_guards=['Append predecessor term must match; conflicting committed entries panic; incoming commit is bounded by matched appended extent.','Heartbeat commit sent is min(peer Match, leader commit). Snapshot restore rejects stale indexes and missing recipient membership.'],writes=['Uncommitted conflicting suffix is replaced; snapshot can fast-forward an already matching committed prefix or replace unstable log and restore configuration.'],external_effects=['Append responses enter the durability-delayed queue; heartbeat echoes read context. Snapshot/probe transitions and heartbeat-triggered empty appends allow retries after loss.'],produces_fact_ids=['f-commit'],cross_activity_effects={'A1':'Follower acknowledgements supply log support; learned commitment is distinct from local quorum calculation.','A2':'Snapshots restore membership while preserving committed history.'})
b('b-persistence','A6','RawNode readyWithoutAccept/newStorageAppendMsg; external storage owner; raft.Step','Stable storage and in-progress unstable data across terms','Ready emission and subsequent Advance or ordered append-worker responses',['s-durable-send','s-ready-output','s-storage-response','s-ready-completion','s-term-dispatch','s-async-contract','s-storage-interface','s-unstable-role','s-initial-state','s-load-state'],legal_preconditions=['Storage presents persisted log and initial HardState/ConfState. Async append requests to one local worker are reliable and ordered; response-carrying writes are durable before responses.'],writes=['Ready acceptance marks unstable data in progress, clears emitted message queues and tracks HardState; completion stabilizes matching indexes and terms.'],important_branches=['Synchronous Ready includes external durability-delayed responses while self-responses are deferred to Advance.','Async append response carries current Raft term as well as entry term/index to reject stale completions after intervening overwrite histories.','Restart reconstructs log, configuration, term/vote/commit and caller-supplied Applied; becomes follower.'],cross_activity_effects={'A1':'Durability-delayed append replies qualify counted support.','A2':'Persistent term/vote and delayed vote publication constrain repeat voting across crashes.'},unknowns=['README/doc.go permit same-batch send/persist overlap while Ready requires entries before messages; which usage contract governs that overlap remains disputed.'])
b('b-application','A5','RawNode Ready/acceptReady/Advance; raft.appliedTo; application or async apply worker','Committed, applying and applied cursors; configuration callback is a separate API','Ready committed entry delivery, synchronous Advance, or MsgStorageApplyResp',['s-log-delivery','s-log-apply','s-apply-response','s-ready-completion','s-applied-auto','s-node-completion-contract','s-node-loop','s-raw-interface'],consumes_fact_ids=['f-commit'],produces_fact_ids=['f-applied'],implementation_guards=['Do not return application entries while snapshot is pending. Async application is limited to locally stable entries. Application quota pauses delivery until acknowledgement.'],writes=['acceptReady updates applying and quota. Advance steps a prebuilt MsgStorageApplyResp; appliedTo raises applied to max(previous, result index), releases quota, and may trigger auto-leave.'],important_branches=['The cursor update itself does not invoke ApplyConfChange. Caller separately applies membership through that API.','Node contract permits Advance before application completes while requiring application batches to finish in order; RawNode.Advance describes notification that entries have been applied and saved.'],cross_activity_effects={'A2':'Election guard uses applied cursor as lower bound for scanning unapplied committed configurations.','A4':'Configuration proposal admission and automatic leave-joint consult applied cursor.'},unknowns=['Whether early Advance excludes configuration-containing batches is not stated in the read Node contract; stricter RawNode wording and tests must be reconciled.'])
b('b-reads','A7','Node/RawNode ReadIndex, raft stepLeader, readOnly and consumer','Unique request context, current leadership term, quorum or configured lease','Local/forwarded read request; first current-term commit; matching heartbeat replies',['s-node-read-contract','s-proposal-read-admission','s-release-reads','s-read-correlation','s-read-acks','s-read-result','s-candidate-follower','s-ready-contract'],consumes_fact_ids=['f-commit'],implementation_guards=['Multi-voter leader queues requests until an entry in its term commits. Safe mode registers context, self ack and heartbeat; current voting quorums must acknowledge.','Singleton directly returns committed index. Lease mode relies on configured lease assumptions.'],writes=['ReadState or MsgReadIndexResp retains request context and selected committed index.'],async_boundaries=['Caller waits until application passes the returned index; Node documents silent read request loss and caller retry with fresh context.'],cross_activity_effects={'A1':'Safe read authorization aggregates context-bound voter responses.','A2':'Reset clears active read quorum contexts; queued pre-current-term requests are distinct and can survive reset.'},unknowns=['Can configuration-driven first current-term commitment occur under any legal early-Advance history, leaving precommit requests queued without a later advancement? No bounded completion obligation is inferred because Node explicitly allows loss.'])
F=[dict(id='f-commit',meaning='Local raftLog.committed marks the prefix treated as committed by this instance. Leader advancement uses current-term quorum support; followers learn it from matched append/heartbeat or snapshots. Advancing this cursor does not uniformly release pending reads.',identity={'group':'one Raft instance','index':'log prefix ending at committed'},validity_context='Prefix persists across terms; fresh leader can only directly advance through an index matching its own term under the active voter quorum. Follower paths rely on valid protocol messages and producer bounds.',representation=['raftLog.committed'],durability='HardState.Commit and snapshot metadata are caller-persisted; cursor change is in-memory until persistence.',recovery='newRaft/loadState and snapshot restoration reconstruct committed prefix.',source_ids=['s-log-commit','s-log-append','s-append-receive','s-restore','s-load-state','s-ack-commit','s-config-commit']),dict(id='f-applied',meaning='raftLog.applied records the highest application progress acknowledged to the core. Advance constructs that acknowledgement from the accepted Ready batch, while async apply responses return completed worker entries. The cursor update does not establish that ApplyConfChange has been invoked.',identity={'node':'local Raft instance','index':'acknowledged applied prefix'},validity_context='Committed entries remain valid across term changes. Caller completion policy determines whether acknowledgement coincides with completed state-machine/configuration application; Node explicitly permits some early Advance.',representation=['raftLog.applied','stepsOnAdvance MsgStorageApplyResp','MsgStorageApplyResp.Entries'],durability='Volatile cursor; caller may supply Config.Applied on restart.',recovery='Initialization uses storage compaction boundary and optional Config.Applied; completed snapshots also advance application accounting.',source_ids=['s-log-apply','s-apply-response','s-ready-completion','s-node-completion-contract','s-applied-auto','s-initial-state'],unknowns=['Does the caller contract permit advancing the cursor past committed membership entries before ApplyConfChange, and if so what protects elections during the interval?'])]
